# Test 2: Keep only 8s that are in rows with no gaps in their span
def rule_gaps(grid):
    output = [[bg]*27 for _ in range(10)]
    for r in range(10):
        cols = [c for c in range(27) if grid[r][c] == 8]
        # Check if cols form a contiguous block
        if len(cols) > 1:
            min_c, max_c = min(cols), max(cols)
            all_present = all(input_d[r][c] == 8 for c in range(min_c, max_c+1))
            if all_present:
                # Keep this row as-is
                for c in range(min_c, max_c+1):
                    output[r][c] = 8
    return output

# Test 3: For each connected component of 8s, shift it based on its position
def rule_components(grid):
    from collections import deque
    output = [[bg]*27 for _ in range(10)]

    visited = set()
    for r in range(10):
        for c in range(27):
            if (r, c) not in visited and input_d[r][c] == 8:
                # BFS to find component
                component = set()
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    cr, cc = q.popleft()
                    component.add((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 10 and 0 <= nc < 27:
                            if (nr, nc) not in visited and input_d[nr][nc] == 8:
                                visited.add((nr, nc))
                                q.append((nr, nc))

                # Now, for each cell in component, move it to a new position
                # Based on component's "anchor" point
                min_r, max_r = min(cp[0] for cp in component), max(cp[0] for cp in component)
                min_c, max_c = min(cp[1] for cp in component), max(cp[1] for cp in component)

                # Move each cell to (r - min_r + 7, c - min_c)
                new_min_r, new_max_r = min_r - min_r + 6, max_r - min_r + 6
                new_min_c, new_max_c = min_c - min_c, max_c - min_c
                for rc, cc in component:
                    nr = rc - min_r + 6
                    nc = cc - min_c
                    if 0 <= nr < 10 and 0 <= nc < 27:
                        output[nr][nc] = 8

    return output

